function makeDraggable(li, list) {
  let drag = null;

  li.addEventListener("pointerdown", (e) => {
    if (e.pointerType === "mouse" && e.button !== 0) return;
    const rect = li.getBoundingClientRect();
    drag = {
      li,
      ul: list,
      startY: e.clientY,
      grabDY: e.clientY - rect.top, // offset from pointer to the top of the item
      moved: false
    };
    li.setPointerCapture(e.pointerId);
    e.preventDefault();
