// ---- Drag & drop (Pointer Events; работает в Chrome/Firefox/Safari, мышь и тач) ----
function makeDraggable(li) {
  let drag = null;

  li.addEventListener("pointerdown", (e) => {
    if (e.pointerType === "mouse" && e.button !== 0) return;
    const rect = li.getBoundingClientRect();
    drag = {
      li,
      grabDY: e.clientY - rect.top, // сдвиг указателя от верхнего края элемента
      startY: e.clientY,
      moved: false
    };
    li.setPointerCapture(e.pointerId);
    e.preventDefault();
  });

  li.addEventListener("pointermove", (e) => {
    if (!drag) return;
    if (!drag.moved) {
      if (Math.abs(e.clientY - drag.startY) < 5) return; // порог: клик ≠ drag
      drag.moved = true;
      drag.li.classList.add("is-dragging");
    }
    const ul = drag.li.parentElement;
    const targetTop = e.clientY - drag.grabDY; // желаемая верхушка элемента (viewport)

    // определяем место вставки среди соседей
    let before = null;
    for (const k of Array.from(ul.children)) {
      if (k === drag.li) continue;
      const r = k.getBoundingClientRect();
      if (targetTop < r.top + r.height / 2) { before = k; break; }
    }
    ul.insertBefore(drag.li, before);

    // плавное следование за указателем
    const r = drag.li.getBoundingClientRect();
    drag.li.style.transform = `translateY(${(targetTop - r.top).toFixed(1)}px)`;
    updatePosMarkers();
  });

  const endDrag = () => {
    if (!drag) return;
    const li = drag.li;
    drag = null;
    li.classList.remove("is-dragging");
    li.style.transition = "transform .12s ease";
    li.style.transform = "";
    li.addEventListener("transitionend", () => { li.style.transition = ""; }, { once: true });
    updatePosMarkers();
  };
  li.addEventListener("pointerup", endDrag);
  li.addEventListener("pointercancel", endDrag);
}

