// ---- Drag & drop (Pointer Events, работает в Chrome/Firefox/Safari, тач+мышь) ----
function makeDraggable(li, list) {
  let drag = null;
  li.addEventListener("pointerdown", (e) => {
    if (e.button !== undefined && e.button !== 0 && e.pointerType === "mouse") return;
    const ul = li.parentElement;
    const rect = li.getBoundingClientRect();
    drag = {
      li, ul,
      startY: e.clientY,
      offsetY: e.clientY - rect.top,
      moved: false,
      lastIdx: Array.from(ul.children).indexOf(li),
      w: rect.width
    };
    li.setPointerCapture(e.pointerId);
    e.preventDefault();
  });
  li.addEventListener("pointermove", (e) => {
    if (!drag) return;
    const dy = e.clientY - drag.startY;
    if (!drag.moved && Math.abs(dy) < 4) return;
    if (!drag.moved) {
      drag.moved = true;
      drag.li.classList.add("is-dragging");
      drag.li.style.height = drag.li.offsetHeight + "px";
      drag.li.style.willChange = "transform";
    }
    // пересчёт позиции относительно списка
    const ulRect = drag.ul.getBoundingClientRect();
    const offsetInUl = (e.clientY - ulRect.top) - drag.offsetY;
    const kids = Array.from(drag.ul.children).filter(x => x !== drag.li);
    let insertBefore = null;
    for (const k of kids) {
      const kr = k.getBoundingClientRect();
      if (offsetInUl < kr.top + kr.height / 2) { insertBefore = k; break; }
    }
    if (insertBefore) drag.ul.insertBefore(drag.li, insertBefore);
    else drag.ul.appendChild(drag.li);
    const base = Array.from(drag.ul.children).indexOf(drag.li);
    // визуальное смещение
    const cur = drag.li.getBoundingClientRect();
    const targetTop = e.clientY - drag.offsetY - ulRect.top;
    const curTop = cur.top - ulRect.top;
    // перемещение относительно текущего DOM-места
    const delta = (targetTop - curTop);
    drag.li.style.transform = `translateY(${delta + (drag.li.style.transform ? 0 : 0)}px)`;
    // проще: держим transform накопительно
    updatePosMarkers();
  });
  const endDrag = (commit) => {
    if (!drag) return;
    drag.li.classList.remove("is-dragging");
    drag.li.style.transform = "";
    drag.li.style.willChange = "";
    drag = null;
    updatePosMarkers();
  };
  li.addEventListener("pointerup", () => endDrag(true));
  li.addEventListener("pointercancel", () => endDrag(false));
}

