const { spawn } = require('child_process');
const fs = require('fs');
async function sleep(ms){return new Promise(r=>setTimeout(r,ms));}
async function main(){
const port = 9445;
const dir = fs.mkdtempSync('/tmp/cdp-dbg-');
const ch = spawn('/usr/bin/google-chrome', ['--headless=new','--no-sandbox','--disable-gpu',`--remote-debugging-port=${port}`,`--user-data-dir=${dir}`,'about:blank'], {stdio:'ignore'});
let target=null;
for(let i=0;i<50&&!target;i++){await sleep(200);try{const r=await fetch(`http://127.0.0.1:${port}/json`);const l=await r.json();target=l.find(t=>t.type==='page');}catch(_){}}
if(!target) throw new Error('no target');
const ws=new WebSocket(target.webSocketDebuggerUrl);
let id=0;const pend=new Map();
const send=(m,p={})=>new Promise((res,rej)=>{const mid=++id;pend.set(mid,{res,rej});ws.send(JSON.stringify({id:mid,method:m,params:p}));});
ws.onmessage=(m)=>{const j=JSON.parse(m.data);
  if(j.id&&pend.has(j.id)){const{res,rej}=pend.get(j.id);pend.delete(j.id);j.error?rej(new Error(JSON.stringify(j.error))):res(j.result);}
  else if(j.method==='Runtime.exceptionThrown'){console.log('PAGE EXCEPTION:',JSON.stringify(j.params.exceptionDetails,null,1));}
  else if(j.method==='Runtime.consoleAPICalled'){console.log('CONSOLE', j.params.type, JSON.stringify(j.params.args).slice(0,500));}
};
await new Promise(r=>ws.onopen=r);
await send('Runtime.enable');await send('Page.enable');
await send('Page.navigate',{url:'file://'+process.cwd()+'/index.html'});
await sleep(1200);
const r=await send('Runtime.evaluate',{expression:'1+1',returnByValue:true});
console.log('1+1 =', r.result.value, r.exceptionDetails ? JSON.stringify(r.exceptionDetails) : '(ok)');
console.log('title =', (await send('Runtime.evaluate',{expression:'document.title',returnByValue:true})).result.value);
const cards = (await send('Runtime.evaluate',{expression:'document.querySelectorAll(".card").length + " cards, " + document.querySelectorAll(".list li").length + " items"',returnByValue:true})).result.value;
console.log(cards);
ch.kill();process.exit(0);
}
main().catch(e=>{console.error(e.message);process.exit(1);});

